    listBookings: {
        parameters: {
            query?: {
                /** @description Include bookings whose `checkOut` is after this date (i.e. still relevant on/after `from`). */
                from?: string;
                /** @description Include bookings whose `checkIn` is on or before this date - together with `from`, a proper closed-range/half-open-stay overlap test (so `from=to=<today>` finds a booking checking in today). */
                to?: string;
                status?: components["schemas"]["BookingStatus"];
                /** @description Case-insensitive substring match against `guestName` - lets a phone-sized "charge to room" picker search by typing instead of scrolling a long list of same-day bookings. Not available on `GET /bookings/export` (that stays a bulk date-range report, not a guest lookup tool). */
                guestName?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Matching bookings, ordered by `checkIn` ascending. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Booking"][];
                };
            };
            401: components["responses"]["Unauthorized"];
        };
    };
